INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(26701, 'Acts 26:9', 'Acts', 26, 9, '&nbsp;خو په حقيقت کښې ما اول هم دا خبره ضرورى ګڼله چې د عيسىٰ ناصرى د نوم خلاف ډېر څۀ کارونه وکړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26702, 'Acts 26:10', 'Acts', 26, 10, '&nbsp;او په يروشلم کښې ما هم دغه شان وکړل، د مشرانو اِمامانو په واک او اختيار مې ډېر مقدسين قېدخانو ته واچول او کله چې به په هغوئ د مرګ فتوىٰ لګېدله نو زما رائ به هم ورسره وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26703, 'Acts 26:11', 'Acts', 26, 11, '&nbsp;ما په ټولو عبادتخانو کښې هغوئ ته سزا ورکوله او کوشش مې دا وو چې دوئ په دې مجبور شى چې کُفر ووائى او زۀ هغوئ ته دومره ډېر غصه وم چې د هغوئ د زورولو پسې به نورو مُلکونو او ښارونو ته هم تلم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26704, 'Acts 26:12', 'Acts', 26, 12, '&nbsp;دغسې په دې سوچ سره زۀ د مشرانو اِمامانو په اختيار او حکم د دمشق په سفر روان وم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26705, 'Acts 26:13', 'Acts', 26, 13, '&nbsp;نو اے بادشاه سلامت، کله چې زۀ په غرمه کښې په لاره روان وم نو ما د آسمان نه يوه رڼا وليدله چې د نمر نه هم زياته تېزه وه، دا زما او زما د ملګرو نه ګېرچاپېره وځلېده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26706, 'Acts 26:14', 'Acts', 26, 14, '&nbsp;کله چې مونږ ټول په زمکه پرېوتلو نو ما په عبرانۍ ژبه کښې يو آواز واورېدلو چې ما ته يې داسې ووئيل چې، ”ساؤله، ساؤله، تۀ ما ولې زوروې؟ موږى ته لته ورکول به تا ته ګران پرېوځى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26707, 'Acts 26:15', 'Acts', 26, 15, '&nbsp;ما جواب ورکړو چې، ”مالِکه، تۀ څوک يې؟“ بيا هغۀ ما ته وفرمائيل چې، ”زۀ عيسىٰ ناصرى يم چې تۀ يې زوروې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26708, 'Acts 26:16', 'Acts', 26, 16, '&nbsp;خو اوس پاڅه، او نېغ په خپلو پښو ودرېږه. زۀ د دې دپاره تا ته ښکاره شوم چې تا خپل خِدمتګار او ګواه مقرر کړم. او چې دُنيا ته تۀ د دې څيزونو ګواهى ورکړې کوم چې تا وليدل او څۀ چې به وروستو زۀ تا ته ښکاره کړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26709, 'Acts 26:17', 'Acts', 26, 17, '&nbsp;زۀ به تا د خپلو خلقو او د غېر‌يهوديانو نه بچ کړم، چا ته چې زۀ تا لېږم', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26710, 'Acts 26:18', 'Acts', 26, 18, '&nbsp;چې د هغوئ سترګې کولاو کړې، او هغوئ د تيارې نه رڼا ته او د شېطان د اختيار نه خُدائ پاک ته راواړوې، چې هغوئ ته د ګناهونو نه معافى مِلاو شى. او د هغوئ سره ورته ځائ مِلاو شى څوک چې په ما د ايمان راوړلو په وسيله مقدس شوى دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26711, 'Acts 26:19', 'Acts', 26, 19, '&nbsp;نو ځکه اے اګريپا بادشاه، زۀ د دې آسمانى رويا نه نافرمانه نۀ شوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26712, 'Acts 26:20', 'Acts', 26, 20, '&nbsp;زۀ د ټولو نه اول د دمشق اوسېدونکو ته راغلم او بيا يروشلم ته لاړم او د يهوديه ټولې علاقې او غېر‌يهوديانو ته مې هم دا اعلان وکړو چې دوئ دې توبه ګار شى او خُدائ پاک ته دې رجوع وکړى. او داسې عملونه دې وکړى چې د دوئ توبه ترې ښکاره شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26713, 'Acts 26:21', 'Acts', 26, 21, '&nbsp;په دغه وجه يهوديانو زۀ د خُدائ په کور کښې ونيولم او زما د وژلو کوشش يې وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26714, 'Acts 26:22', 'Acts', 26, 22, '&nbsp;خو تر ننه پورې خُدائ پاک زما مل دے، نو ځکه زۀ دلته ستاسو په وړاندې ولاړ يم او لويو او وړو ته دا ګواهى ورکوم د څۀ چې نبيانو او موسىٰ پېشګوئې کړې ده، د دې نه بغېر نور څۀ نۀ وايم،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26715, 'Acts 26:23', 'Acts', 26, 23, '&nbsp;يعنې دا چې مسيح به ضرور سختې وزغمى او هغه به د مړو نه اول بيا راژوندے شى، او په داسې کولو سره به هغه زمونږ خلقو او غېر‌يهوديانو دواړو ته د رڼا اِعلان وکړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26716, 'Acts 26:24', 'Acts', 26, 24, '&nbsp;لا پولوس په خپله صفائى کښې خبرې کولې چې فِستوس په اوچت آواز ووئيل چې، ”پولوسه، تۀ ليونے يې، ستا ډېر عِلم تۀ ليونے کړے يې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26717, 'Acts 26:25', 'Acts', 26, 25, '&nbsp;خو پولوس ووئيل چې، ”اے معزز فِستوسه، زۀ ليونے نۀ يم، څۀ چې زۀ وايم هغه د اعتماد قابل او رښتيا دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26718, 'Acts 26:26', 'Acts', 26, 26, '&nbsp;بادشاه په دغه خبرو ښۀ خبر دے او هغۀ سره زۀ په زړۀ ورتيا خبرې کوم. زۀ دا يقين ساتم چې دا واقعې د هغۀ نه پټې نۀ دى، ځکه چې دا څۀ پټه واقعه نۀ ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26719, 'Acts 26:27', 'Acts', 26, 27, '&nbsp;نو اے اګريپا بادشاه، ولې تۀ په نبيانو ايمان ساتې؟ ما ته پته ده چې ستا په هغوئ ايمان شته.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26720, 'Acts 26:28', 'Acts', 26, 28, '&nbsp;اګريپا پولوس ته ووئيل چې، ”په لږ وخت کښې به تۀ ما قائل کړې چې عيسائى شم؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26721, 'Acts 26:29', 'Acts', 26, 29, '&nbsp;پولوس جواب ورکړو چې، ”زر يا وروستو، زۀ د خُدايه دا دُعا کوم چې نۀ يواځې تۀ بلکې هغوئ ټول چې نن زما خبرې اورى، هغوئ دې بغېر د زولنو نه زما په شان شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26722, 'Acts 26:30', 'Acts', 26, 30, '&nbsp;بيا بادشاه او هغۀ سره ګورنر، او بِرنيکى او څوک چې ورسره ناست وو هغوئ پاڅېدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26723, 'Acts 26:31', 'Acts', 26, 31, '&nbsp;او چې هغوئ تلل نو يو بل ته هغوئ ووئيل چې، ”دې سړى داسې څۀ کار نۀ دے کړے چې د مرګ يا د قېد لائق وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26724, 'Acts 26:32', 'Acts', 26, 32, '&nbsp;خو اګريپا فِستوس ته ووئيل چې، ”کۀ دې سړى قيصر ته اپيل نۀ وے کړے نو دے آزادېدے شو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26725, 'Acts 27:1', 'Acts', 27, 1, '&nbsp;کله چې دا فېصله وشوه چې مونږ به اِټلى ته په سمندرى جهاز کښې ځو نو پولوس او څۀ نور قېديان د قيصر د پلټنې يو صوبه دار يوليوس ته وسپارلے شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26726, 'Acts 27:2', 'Acts', 27, 2, '&nbsp;بيا مونږ د ادرمتيم ښار په يوه کشتۍ کښې کښېناستو چې د آسيه د صوبې بندرګاهو ته تلو او په سمندر کښې روان شُو. زمونږ په ملګرو کښې د تِسالونيکيه يو مِکدونى سړے وو چې نوم يې اريسترخوس وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26727, 'Acts 27:3', 'Acts', 27, 3, '&nbsp;په بله ورځ مونږ په صيدا کښې کوز شُو او يوليوس ډېر په مهربانۍ پولوس ته اجازت ورکړو چې خپلو دوستانو ته ورشى نو چې هغوئ د هغۀ ضرورتونه پوره کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26728, 'Acts 27:4', 'Acts', 27, 4, '&nbsp;چې د هلته نه روان شُو نو په سمندر کښې د تېزې سيلۍ په وجه مونږ د قبرص د جزيرې په ژۍ ژۍ کښې لاړو ځکه چې هلته هوا کمه لګېده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26729, 'Acts 27:5', 'Acts', 27, 5, '&nbsp;د کلکيه او د پمفوليه د سمندر نه د تېرېدو نه وروستو مونږ په لکيه کښې ميره نومې ښار ته راغلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26730, 'Acts 27:6', 'Acts', 27, 6, '&nbsp;هلته صوبه دار د اسکندريه يو جهاز وموندلو چې اِټلى ته روان وو او مونږ يې په کښې سوارۀ کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26731, 'Acts 27:7', 'Acts', 27, 7, '&nbsp;تر ډېرو ورځو پورې مونږ ډېر ورو ورو تلو او کنيدوس ته په ډېر تکليف ورسېدو. او چې هوا زمونږ مخالف وه نو مونږ د کريت په ژۍ ژۍ کښې سلمونې ته لاړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26732, 'Acts 27:8', 'Acts', 27, 8, '&nbsp;په مشکل سره مونږ د سمندر په غاړه تلو، بيا مونږ يو ځائ ته راغلو چې نوم يې ښائسته بندرګاه وه چې د لسيه ښار سره نزدې وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26733, 'Acts 27:9', 'Acts', 27, 9, '&nbsp;اوس کافى وخت تېر شوے وو او په سمندرى سفر تلل خطرناک وُو ځکه چې روژه هم تيره شوې وه. نو پولوس هغوئ ته دا مشوره ورکړه', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26734, 'Acts 27:10', 'Acts', 27, 10, '&nbsp;او وې وئيل چې، ”اے عزتمندو، ما ته ښکارى چې دا سفر به خطرناک وى او دا به يو لوئ نقصان وى، نۀ صرف د جهاز او د سامان بلکې زمونږ د ژوند تاوان به هم وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26735, 'Acts 27:11', 'Acts', 27, 11, '&nbsp;خو پولوس چې څۀ ووئيل نو صوبه دار د هغې په ځائ د ماڼکى او د جهاز د مالِک رايه زياته بهتره وګڼله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26736, 'Acts 27:12', 'Acts', 27, 12, '&nbsp;ځکه چې هغه بندرګاه د ژمى د موسم د تېرولو دپاره مناسب نۀ وه نو ډېرو خلقو د سمندر د سفر رايه خوښه کړه او اُميد يې وو چې فنيکس ته به ورسيږى او هلته به ژمے تير کړى، دا د کريت د جزيرې يوه بندرګاه ده چې مخ يې جنوب مغرب ته او شمال مغرب ته دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26737, 'Acts 27:13', 'Acts', 27, 13, '&nbsp;کله چې د جنوب نه نرۍ هوا راوالوته نو هغوئ ګُمان وکړو چې هغوئ خپل مقصد تر سره کولے شى، نو لنګر يې پورته کړو او غاړې ته نزدې د کريت په ژۍ ژۍ کښې روان شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26738, 'Acts 27:14', 'Acts', 27, 14, '&nbsp;خو ډېر وخت نۀ وو تېر شوے چې يوه طوفانى هوا د جزيرې نه راوالوته چې ورته شمال مشرقى هوا وائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26739, 'Acts 27:15', 'Acts', 27, 15, '&nbsp;نو چې جهاز ګېر شو او په طوفان کښې مخکښې نه شو تلے، نو مونږ ورته لاره ورکړه او هوا سره روان شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26740, 'Acts 27:16', 'Acts', 27, 16, '&nbsp;مونږ د کاوده نومې يوې ورکوټې جزيرې په ژۍ ژۍ کښې لاړو او هلته مو په مشکل سره د جهاز کِشتۍ قابو کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26741, 'Acts 27:17', 'Acts', 27, 17, '&nbsp;جهاز ته يې د خېژولو نه وروستو د حفاظت دپاره کشتۍ په پړو وتړله، بيا هغوئ په دې يرېدل چې هسې نه د سرتيس په شګو کښې ونښلى، نو هغوئ سمندر ته لنګر ورکوز کړو او جهاز يې د هوا په مخ روان کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26742, 'Acts 27:18', 'Acts', 27, 18, '&nbsp;په بله ورځ چې ډېر سخت طوفان وو نو هغوئ د جهاز نه بوج کمولو دپاره سامان غورزول شروع کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26743, 'Acts 27:19', 'Acts', 27, 19, '&nbsp;او په درېمه ورځ يې د جهاز آوزار په خپلو لاسونو وغورزولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26744, 'Acts 27:20', 'Acts', 27, 20, '&nbsp;کله چې تر ډېرو ورځو، نۀ نمر ښکارېدو او نۀ ستورى، بلکې سخت طوفان چلېدو نو آخر زمونږ د بچ کېدو ټول اُميد هم ختم شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26745, 'Acts 27:21', 'Acts', 27, 21, '&nbsp;هغوئ د ډېرو ورځو نه بې‌خوراکه وُو، نو پولوس د هغوئ په مينځ کښې ودرېدو او وې وئيل چې، ”اے عزتمندو، تاسو ته په کار وو چې د کريت نه د سفر د نۀ کولو په حقله زما خبره مو منلے وے، نو د دې نقصان او تاوان نه به بچ شوى وئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26746, 'Acts 27:22', 'Acts', 27, 22, '&nbsp;خو اوس زۀ درته نصيحت کوم چې زړونه مۀ بائيلئ ځکه چې په تاسو کښې به هيڅ څوک هم مړ نۀ شى خو صرف جهاز به غرق شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
