(26789, 'Acts 28:21', 'Acts', 28, 21, '&nbsp;هغوئ جواب ورکړو چې، ”مونږ ته د يهوديه نه هيڅ داسې خط نۀ دے راغلے او نۀ څوک زمونږ ورور د دې اِطلاع راکولو دپاره دلته راغلے دے چې ستا په حقله يې بد وئيلى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26790, 'Acts 28:22', 'Acts', 28, 22, '&nbsp;خو مونږ ستا نه اورېدل غواړو چې ستا څۀ خيال دے، ځکه چې مونږ ته پته ده چې هر چرته د دې فرقې خلاف خبرې کيږى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26791, 'Acts 28:23', 'Acts', 28, 23, '&nbsp;هغوئ د هغۀ سره د وخت مقررولو نه وروستو په ګڼ شمېر کښې د هغۀ کور ته راغلل. هغوئ ته د سحر نه تر ماښامه پورې هغۀ د خُدائ پاک بادشاهى بيان کړه او ګواهى يې ورکړه او دا کوشش يې وکړو چې د موسىٰ د شريعت او د نبيانو د صحيفو دواړو نه هغوئ د عيسىٰ په حقله قائل کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26792, 'Acts 28:24', 'Acts', 28, 24, '&nbsp;ځينې خو د هغۀ په وينا سره قائل شول خو ځينو په هغۀ باور ونۀ کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26793, 'Acts 28:25', 'Acts', 28, 25, '&nbsp;نو د هغوئ په مينځ کښې بې‌اتفاقى راغله کله چې هغۀ يوه خبره وکړه نو هغوئ روان شول. نو د پولوس هغه خبره دا وه چې، ”د يشعياه نبى په وسيله روحُ القُدس ستاسو پلار نيکونو ته ښۀ وئيلى وُو چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26794, 'Acts 28:26', 'Acts', 28, 26, '&nbsp;”دې خلقو له ورشه او ورته ووايه، تاسو به يې په خپلو غوږونو واورئ خو پوهه به پرې نۀ شئ، تاسو به يې په خپلو سترګو ووينئ خو او به پرې نۀ رسېږئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26795, 'Acts 28:27', 'Acts', 28, 27, '&nbsp;ځکه چې د دې اُمت زړونه سخت شوى دى، او په مشکله سره خبرې ته غوږ ږدى او سترګې يې پټې کړې دى. هسې نه چې هغوئ په خپلو غوږونو واورى او په خپلو سترګو ووينى او خپل زړونه نرم کړى او ما ته واپس راوګرځى او زۀ هغوئ روغ کړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26796, 'Acts 28:30', 'Acts', 28, 30, '&nbsp;نو هغه هلته پوره دوه کاله په خپله خرچه اوسېدو او هر هغه چا ته به يې هرکلے وئيلو، څوک چې به هغۀ له راتلل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26797, 'Acts 28:31', 'Acts', 28, 31, '&nbsp;او هغۀ د خُدائ پاک د بادشاهۍ بيان کولو او د مالِک عيسىٰ مسيح په حقله يې په زړۀ ورتيا او بغېر د څۀ پابندۍ تعليم ورکولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26798, 'Romans 1:1', 'Romans', 1, 1, '&nbsp;د پولوس د طرف نه، چې د عيسىٰ مسيح خادِم او بللے شوے رسول دے څوک چې د خُدائ پاک د زيرى د خورولو دپاره مقرر کړے شوے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26799, 'Romans 1:2', 'Romans', 1, 2, '&nbsp;د دې زېرى وعده خُدائ پاک د مخکښې نه په مقدسو صحيفو کښې د خپلو نبيانو په وسيله کړې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26800, 'Romans 1:3', 'Romans', 1, 3, '&nbsp;دا زيرے د هغۀ د زوئ په حقله دے، څوک چې په انسانى طور د داؤد په نسل کښې پېدا شو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');